{
  "a_sentences": [
    {
      "a_text": "P1 La question litigieuse porte sur la transposition de la jurisprudence relative aux personnes déjà au chômage au cas d'une personne exerçant un travail sur appel.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "P2 Selon les constatations cantonales, la personne assurée est restée en incapacité de travail totale à compter du 1er septembre 2022.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "P3 La juridiction cantonale retient que la personne assurée ne peut plus exercer son travail sur appel et qu'il est douteux qu'un nouvel emploi lui procure un revenu.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "P4 Le Tribunal fédéral rappelle qu'une personne au chômage qui réclame des indemnités journalières de l'assurance-maladie doit prouver un manque à gagner.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "P5 P5 Le Tribunal fédéral précise que l'exigence n'est pas celle de la preuve d'une occupation à un poste précis, mais bien celle d'un manque à gagner.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "P6 Le Tribunal fédéral estime qu'une instruction complémentaire n'est pas nécessaire, car la décision cantonale ne convainc pas s'agissant de l'expiration de la période de cotisation de l'assurance-chômage.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "P7 P7 Le Tribunal fédéral conclut que le doute sur la persistance d'un revenu aux anciens postes n'est pas déterminant, car un manque à gagner est de toute façon survenu avec une vraisemblance prépondérante.",
      "b_propositions": ["P7"]
    }
  ]
}
